(7122326, 1087901, 114225, '<td valign="top">Cute idea!</td>', 'Cute idea!', '2013-10-27 19:18:23.000000', NULL, 1),
(7122327, 1087942, 170281, '<td valign="top">Very nice sunburst shot!  The lines in the tree make for a very interesting photograph.  I think a bit more depth of field would be a nice enhancement, but that is my style more than anything.</td>', 'Very nice sunburst shot!  The lines in the tree make for a very interesting photograph.  I think a bit more depth of field would be a nice enhancement, but that is my style more than anything.', '2013-10-27 19:18:44.000000', NULL, 1),
