INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7123204, 1087620, 63398, '<td valign="top">Outstanding! *VERY* nice shot, and congrats on a fine finish!</td>', 'Outstanding! *VERY* nice shot, and congrats on a fine finish!', '2013-10-29 14:47:51.000000', NULL, 0),
