(7123896, 1087597, 18197, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by mitalapo:</b></div><hr/><i> reminds me of a certain <a href="//i14.photobucket.com/albums/a306/Gracie0009/Down%20to%20Earth/camel-wall-paper.jpg" rel="nofollow" target="_blank">natgeo camels at sunrise</a> shot... </i></td></tr></table> <br/> <br/>Thanks for noticing  that was my intention.</td>', 'Originally posted by mitalapo: reminds me of a certain natgeo camels at sunrise shot...   Thanks for noticing  that was my intention.', '2013-10-31 17:13:10.000000', NULL, 0),
